"""Merged native array query, exact +2, both short-name tables, monotonic menu order."""
from pathlib import Path
import json,sqlite3,collections
import organize_seasons as s
out=Path(s.read(s.R/'latest-build.json')['path']);data=s.read(out/'build.json');roster=s.read(out/'static_roster.json');old=s.read(s.S/'responses/static_roster.json');w=s.weights()
assert len(roster['seasons'])==len(old['seasons'])-2
assert collections.Counter(i for row in roster['seasons'] for i in row['value'])==collections.Counter(i for row in old['seasons'] for i in row['value'])
assert [row['value'] for row in roster['seasons'] if set(row['value'])&{48,49,55}]==[[48,49,55]]
old_other={tuple(row['value']):row for row in old['seasons'] if not set(row['value'])&{48,49,55}}
new_other={tuple(row['value']):row for row in roster['seasons'] if not set(row['value'])&{48,49,55}};assert old_other==new_other
db=sqlite3.connect(out/'fifadb.sqlite');db.row_factory=sqlite3.Row;ratings=[]
for entry in roster['seasons']:
 values=[s.primary(dict(row),w)+5 for row in db.execute('select * from players where spid/1000000 in ('+','.join('?' for _ in entry['value'])+')',entry['value'])];ratings.append(sum(values)/len(values))
assert ratings==sorted(ratings,reverse=True)
for changed in data['ratings']:
 row=dict(db.execute('select * from players where spid=?',(changed['spid'],)).fetchone());assert s.primary(row,w)+5==changed['after_level1_plus1']==changed['before_level1_plus1']+2
primary48=[r['after_level1_plus1'] for r in data['ratings'] if r['spid']//1000000==48];assert min(primary48)==90 and max(primary48)==94
for file,table in [('fifadb.sqlite','nameschi'),('chi.sqlite','names')]:
 with sqlite3.connect(out/file) as names:
  for pid,label in s.NAMES.items():assert names.execute('select short from '+table+' where playerid=?',(pid,)).fetchone()[0]==label
proof=s.read(s.R/'native-order-proof.json')
assert 'callproperty push (1)' in proof['TransferPurchaseFilterSmoothPanel:51'] and 'sort' not in proof['TransferPurchaseFilterSmoothPanel:51']
assert 'forEach' in proof['TransferUtil:26'] and 'OR ' in proof['TransferUtil:25']
# Execute the exact BETWEEN/OR structure generated by TransferUtil25/26.
where=' OR '.join('(p.spid BETWEEN '+str(i*1000000)+' AND '+str((i+1)*1000000-1)+')' for i in (48,49,55))
rows=list(db.execute('select p.spid,n.short from players p join nameschi n using(playerid) join permid m using(spid) where ('+where+') and m.transferable=1 and m.licensed=1 group by p.spid order by p.overallrating desc,p.spid asc limit 200'))
assert len(rows)==53 and all('shortname' not in r['short'].casefold() for r in rows)
# Confirm the independent native Chinese library's unrelated tables as well.
raw=bytes(s.codec.extract_fifadb.decrypt(s.codec.bigdir.read(s.C/'data/data_0.big','data/db2/chi.db.db2')));baseline=out/'chi-before.sqlite';baseline.write_bytes(b'SQLite format 3\0'+raw[16:])
with sqlite3.connect(out/'chi.sqlite') as chi:
 chi.execute('attach database ? as old',(str(baseline),))
 for table, in chi.execute("select name from main.sqlite_master where type='table'").fetchall():
  where=' where playerid not in (36,239)' if table=='names' else ''
  assert not chi.execute('select * from main.'+table+where+' except select * from old.'+table+where+' limit 1').fetchone()
  assert not chi.execute('select * from old.'+table+where+' except select * from main.'+table+where+' limit 1').fetchone()
p=s.plan();s.write(s.R/'tests.json',dict(status='READY_FOR_DIRECT_INSTALL',ratings_exact_plus2=53,correct_short_names_both_libraries=2,merged_native_sql_results=53,one_MU_entry=True,all_other_entries_retained=True,monotonic_strength_order=True,entry_counts=[len(old['seasons']),len(roster['seasons'])],primary48_range=[min(primary48),max(primary48)],native_array_and_order_bytecode_confirmed=True,latest_parent=p['prior'],targets=len(p['entries']),native_verified=False))
print('53 exact +2 ratings, true short names, one native filter and strength ordering PASS')
